def market_close(hour=0, minute=0):
    minutes_since_midnight = 900 - hour * 60 - minute
    if minutes_since_midnight < 780:
        minutes_since_midnight -= 90
    return minutes_since_midnight
def market_open(hour=0, minute=0):
    minutes_since_midnight = 571 + hour * 60 + minute
    if minutes_since_midnight > 690:
        minutes_since_midnight += 90
    return minutes_since_midnight
